{
  "Q1": {
    "q1_duty_procs": {
      "verdict": "yes",
      "rationale": "Table lists 11046 (2026-14991, 91 FR 46639), 11047 (2026-14992, 91 FR 46653) and 11048 (2026-14997, 91 FR 46663), signed July 20, published July 23, 2026."
    },
    "q1_details": {
      "verdict": "yes",
      "rationale": "All ten documents have correct first pages (46639, 46653, 46663, 54789, 58311, 58319, 58325, 58331, 58339, 68861) and an accurate one-line description each."
    },
    "q1_delay": {
      "verdict": "yes",
      "rationale": "11056 (2026-17294), signed Aug. 18, published Aug. 24, postpones all three duties to 12:01 a.m. Aug. 22, 2026."
    },
    "q1_exclusions": {
      "verdict": "yes",
      "rationale": "11061/11062/11063 with correct doc numbers (2026-18835/-18836/-18837), signed Sept. 8, published Sept. 14, operative 12:01 a.m. Sept. 29 measured by importation."
    },
    "q1_scope": {
      "verdict": "yes",
      "rationale": "11064 (2026-18838) and 11065 (2026-18839) from 12:01 a.m. Sept. 15; 11076 (2026-22292), signed Oct. 23, published Oct. 30, from 12:01 a.m. Oct. 30."
    },
    "q1_events": {
      "verdict": "yes",
      "rationale": "Duties and scope changes are measured by consumption entry or warehouse withdrawal; exclusions are expressly 'measured by importation, not consumption entry.'"
    },
    "q1_dairy_none": {
      "verdict": "yes",
      "rationale": "States dairy got only the exclusion (11062) and 'No actual dairy scope-modification proclamation was located'; alcohol changed by 11064, vehicles by 11065/11076."
    },
    "q1_dairy_xref": {
      "verdict": "yes",
      "rationale": "Uncertainty notes 11062 clause (3) refers to a Sept. 8 dairy scope proclamation and that no such document was found."
    },
    "q1_cite": {
      "verdict": "no",
      "rationale": "Every table row and proposition carries FR document number, clause and page."
    },
    "q1_fab": {
      "verdict": "no",
      "rationale": "No invented document, page or clause; annex content is expressly disclaimed as image-only."
    }
  },
  "Q2": {
    "q2a_zero": {
      "verdict": "yes",
      "rationale": "Entries 1 and 2 are $0 ('$40,000 x 0% during postponement')."
    },
    "q2a_third": {
      "verdict": "yes",
      "rationale": "Entry 3 (12:01 a.m. Aug. 22) = $40,000 x 50% = $20,000."
    },
    "q2a_basis": {
      "verdict": "yes",
      "rationale": "Quotes 11056 clause (1) 'shall be 12:01 a.m. eastern time on August 22, 2026,' citing 2026-17294, 91 FR 54790 (quote verified in key)."
    },
    "q2b_chapeau": {
      "verdict": "yes",
      "rationale": "Says 11056 amends only the Annex II chapeau (Aug. 19 to Aug. 22) and that numbered clauses (1) and (3) still print Aug. 19."
    },
    "q2b_resolve": {
      "verdict": "yes",
      "rationale": "Relies on both the first sentence of 11056(1) setting the date outright and clause (5) superseding inconsistent earlier provisions."
    },
    "q2c_refund": {
      "verdict": "yes",
      "rationale": "Quotes 11056 clause (4) ('processed pursuant to applicable law and CBP's standard procedures') and notes no special procedure/deadline."
    },
    "q2d_no_action": {
      "verdict": "yes",
      "rationale": "Says no further presidential act was needed; later recitals (11061 recitals 2-4) say the suspension lapsed at 12:01 a.m. Aug. 22 and duties became effective."
    },
    "q2d_reneged": {
      "verdict": "yes",
      "rationale": "States Canada's commitment, then that on Aug. 21 it reneged and ceased negotiating in good faith."
    },
    "q2e_thirty": {
      "verdict": "yes",
      "rationale": "Derives Aug. 19 from the 30-day rule: July 20 + 30 days, with day-count arithmetic shown."
    },
    "q2_cite": {
      "verdict": "no",
      "rationale": "Abundant document, clause and page citations."
    },
    "q2_fab": {
      "verdict": "no",
      "rationale": "Quotations checked (11056(1), (4)) exist; no invented sources."
    }
  },
  "Q3": {
    "q3a_shipment_a": {
      "verdict": "yes",
      "rationale": "A: permitted, $30,000 x 50% = $15,000."
    },
    "q3a_shipment_b": {
      "verdict": "yes",
      "rationale": "B: prior import under clause (2), permitted and $15,000."
    },
    "q3a_shipment_c": {
      "verdict": "yes",
      "rationale": "C: imported before 12:01 a.m. Sept. 29, later entry does not trigger ban, $15,000."
    },
    "q3a_shipment_d": {
      "verdict": "yes",
      "rationale": "D: prohibited under clause (1); expressly rejects admission on payment of 50%."
    },
    "q3b_result": {
      "verdict": "yes",
      "rationale": "E: 'most defensible reading' is prior import, not excluded, $15,000 on entry from the zone."
    },
    "q3b_ftz": {
      "verdict": "yes",
      "rationale": "Cites the duty proclamation's privileged-foreign-status zone rule (11046 clause (4)) and notes 11061 has no zone-specific rule."
    },
    "q3c_invalid": {
      "verdict": "yes",
      "rationale": "11061(9)(b): 50% duty under 11046 applies to imports covered by the invalidated ban; $15,000 example."
    },
    "q3d_no_change": {
      "verdict": "yes",
      "rationale": "No; clause (3) leaves products subject to 11046 outside the Annex at 50%."
    },
    "q3_cite": {
      "verdict": "no",
      "rationale": "Each shipment and rule is cited by clause and page."
    },
    "q3_fab": {
      "verdict": "no",
      "rationale": "No invented sources or quotes."
    }
  },
  "Q4": {
    "q4a_amounts": {
      "verdict": "yes",
      "rationale": "Sept. 10: 232 $25,000 and 338 $0 for X, Y and Z."
    },
    "q4a_basis": {
      "verdict": "yes",
      "rationale": "Rests on clause (2) of 11046/11047/11048 ('shall not apply to articles subject to duties pursuant to section 232')."
    },
    "q4b_x": {
      "verdict": "yes",
      "rationale": "X: $25,000 + $50,000, citing 11064(1) from Sept. 15."
    },
    "q4b_z": {
      "verdict": "yes",
      "rationale": "Z: $25,000 + $50,000, citing 11065(1)."
    },
    "q4b_y": {
      "verdict": "yes",
      "rationale": "Y: $25,000 + $0, because no document modified 11047 and its clause (2) carve-out stands."
    },
    "q4c_text": {
      "verdict": "yes",
      "rationale": "Quotes the clause (2) carve-out and the 'in addition to duties imposed pursuant to section 232' sentence of 11064/11065 effective Sept. 15."
    },
    "q4c_supersede": {
      "verdict": "yes",
      "rationale": "Cites clause (7) of the scope proclamations (91 FR 58333, 58341) superseding inconsistent earlier provisions."
    },
    "q4c_xref": {
      "verdict": "yes",
      "rationale": "Uncertainty flags that 11062's reference to a dairy scope proclamation does not establish a change and that no such document was found."
    },
    "q4c_doubt": {
      "verdict": "yes",
      "rationale": "The answer expressly puts the Y result on the absence of any published dairy modification ('No such scope document was found'), one of the key's examples of qualifying the answer for Y, though it is stated in the Uncertainty field rather than as an explicit hedge in (b)."
    },
    "q4_cite": {
      "verdict": "no",
      "rationale": "All layers cited to proclamation, clause and page."
    },
    "q4_fab": {
      "verdict": "no",
      "rationale": "No invented source; quotations match key text."
    }
  },
  "Q5": {
    "q5a_p": {
      "verdict": "yes",
      "rationale": "P: No, Yes, Yes, Yes, Yes."
    },
    "q5a_q": {
      "verdict": "yes",
      "rationale": "Q: Yes, No, No, No, No."
    },
    "q5a_r": {
      "verdict": "yes",
      "rationale": "R: Yes, Yes, Yes, No, No, with 11076 Part A removing coverage."
    },
    "q5a_s": {
      "verdict": "yes",
      "rationale": "S: No, No, No, Yes, Yes, with 11076 Part B adding coverage."
    },
    "q5b_dates": {
      "verdict": "yes",
      "rationale": "Signed Oct. 23, filed Oct. 29 (11:15 a.m.), published Oct. 30, applies from 12:01 a.m. Oct. 30."
    },
    "q5b_prospective": {
      "verdict": "yes",
      "rationale": "Says scope changes are prospective only and the proclamations provide no refunds."
    },
    "q5c_days": {
      "verdict": "yes",
      "rationale": "P and S each became dutiable seven calendar days after signing (Sept. 8-15; Oct. 23-30)."
    },
    "q5c_silent": {
      "verdict": "yes",
      "rationale": "Notes the proclamations recite the 30-day rule but do not explain how 7-day additions fit it, offering only a defensible reading and saying the documents do not resolve it."
    },
    "q5_cite": {
      "verdict": "no",
      "rationale": "Well cited throughout."
    },
    "q5_fab": {
      "verdict": "no",
      "rationale": "No invented sources."
    }
  },
  "Q6": {
    "q6a_switzerland": {"verdict": "yes", "rationale": "$8,500; total $12,500."},
    "q6a_norway": {"verdict": "yes", "rationale": "$12,500 flat; total $16,500."},
    "q6a_uk": {"verdict": "yes", "rationale": "$10,000; total $14,000."},
    "q6a_germany": {"verdict": "yes", "rationale": "$6,000; total $10,000."},
    "q6a_taiwan": {"verdict": "yes", "rationale": "$6,000; total $10,000."},
    "q6a_turkiye": {"verdict": "yes", "rationale": "$12,500; total $16,500."},
    "q6a_japan": {"verdict": "yes", "rationale": "$8,500; total $12,500."},
    "q6a_liechtenstein": {"verdict": "yes", "rationale": "$0 because not an investigated economy; total $4,000."},
    "q6a_hongkong": {"verdict": "yes", "rationale": "$12,500; total $16,500."},
    "q6a_india": {"verdict": "yes", "rationale": "$10,000; total $14,000."},
    "q6b_germany12": {"verdict": "yes", "rationale": "$0 (MFN >= 10%)."},
    "q6b_japan12": {"verdict": "yes", "rationale": "$500 (12.5% - 12%)."},
    "q6b_taiwan10": {"verdict": "yes", "rationale": "$0 (greater than or equal to 10%)."},
    "q6b_korea10": {"verdict": "yes", "rationale": "$2,500 (12.5% - 10%)."},
    "q6b_swiss_free": {"verdict": "yes", "rationale": "$12,500."},
    "q6c_net": {
      "verdict": "yes",
      "rationale": "Identifies Switzerland (12.5%), Germany/EU (10%), Taiwan (10%) and Japan (12.5%) as changed from flat to net of MFN, and says Norway, UK, Türkiye and Hong Kong retain flat rates."
    },
    "q6c_india": {
      "verdict": "yes",
      "rationale": "India 12.5% proposed to 10% adopted, attributed to its adoption of a forced-labor import prohibition."
    },
    "q6_cite": {"verdict": "no", "rationale": "Citations to memorandum sections, notice determinations and note 52(a) throughout."},
    "q6_fab": {"verdict": "no", "rationale": "No invented citations detected."}
  },
  "Q7": {
    "q7a_france": {"verdict": "yes", "rationale": "$60 duty, 0.5% AVE, 9.5% section 301, $1,140."},
    "q7b_italy": {"verdict": "yes", "rationale": "$1,800 / 9% AVE, $200."},
    "q7b_japan": {"verdict": "yes", "rationale": "$700 (3.5%)."},
    "q7b_brazil": {"verdict": "yes", "rationale": "$2,500 flat 12.5%."},
    "q7c_taiwan": {"verdict": "yes", "rationale": "11% AVE, $0."},
    "q7c_switzerland": {"verdict": "yes", "rationale": "$300 (1.5%)."},
    "q7d_note": {"verdict": "yes", "rationale": "U.S. note 52(k), 91 FR 47394: duty payable under column 1-General divided by customs value."},
    "q7d_zero": {"verdict": "yes", "rationale": "Places the at-or-above-cap zero result in memorandum sec. 1(a)(ii) and the notice's determinations, not note 52(k)."},
    "q7_cite": {"verdict": "no", "rationale": "All amounts tied to note 52(k) and determinations with pages."},
    "q7_fab": {"verdict": "no", "rationale": "No invented source."}
  },
  "Q8": {
    "q8a_case1": {"verdict": "yes", "rationale": "$10,000; entry July 29 not before July 28."},
    "q8a_case2": {"verdict": "yes", "rationale": "$0; loaded/in transit before July 24 and entered before July 28."},
    "q8a_case3": {"verdict": "yes", "rationale": "$10,000; 12:01 a.m. July 28 is not 'before'."},
    "q8a_case4": {"verdict": "yes", "rationale": "$10,000; loaded 6:00 a.m. July 24, after the cut-off."},
    "q8a_case5": {"verdict": "yes", "rationale": "$0; entered July 23 before commencement."},
    "q8a_case6": {"verdict": "yes", "rationale": "$10,000; withdrawal July 26 covered; not in transit."},
    "q8a_case7": {"verdict": "yes", "rationale": "$10,000; exception is limited to vessel loading, no air analogue."},
    "q8b_where": {"verdict": "yes", "rationale": "DATES paragraph of 2026-15181 (91 FR 47318), and says it is not in the memorandum."},
    "q8c_dates": {"verdict": "yes", "rationale": "Signed July 23; applies 12:01 a.m. July 24; published July 28."},
    "q8d_july30": {"verdict": "yes", "rationale": "$10,000; pharmaceutical exemption effective July 31."},
    "q8d_aug3": {"verdict": "yes", "rationale": "$0 under note 52(f)(8)/Annex I.B."},
    "q8_cite": {"verdict": "no", "rationale": "Well cited."},
    "q8_fab": {"verdict": "no", "rationale": "No invented source."}
  },
  "Q9": {
    "q9a_assembly": {"verdict": "yes", "rationale": "$65,000 x 12.5% = $8,125 under note 52(a)."},
    "q9b_repairs": {"verdict": "yes", "rationale": "$6,000 x 12.5% = $750."},
    "q9c_usmca": {"verdict": "yes", "rationale": "$0 under note 52(h)."},
    "q9c_no_claim": {"verdict": "yes", "rationale": "$5,000 (flat 10% of $50,000)."},
    "q9d_car": {"verdict": "yes", "rationale": "$0 under note 52(f)(2)."},
    "q9e_reading": {"verdict": "yes", "rationale": "Concludes 12.5% ($12,500) applies in addition to section 232, because note 52(f) lists particular headings and 52(a) makes duties cumulative."},
    "q9e_flag": {
      "verdict": "yes",
      "rationale": "(e) says note 52(f) is 'not a freestanding exemption for every possible section 232 duty,' and (f) contrasts the proposal's general section 232 exemption with the adopted enumerated headings; that is the required caveat, though placed mostly in (f)."
    },
    "q9f_232": {"verdict": "yes", "rationale": "Proposal would exempt all section 232 articles/parts; adopted note 52(f) lists particular headings, with later pharmaceutical addition."},
    "q9f_info": {"verdict": "yes", "rationale": "Proposal listed informational materials, donations and accompanied baggage; adopted readable text has no informational-materials/donation exception."},
    "q9_cite": {"verdict": "no", "rationale": "Note subdivisions and pages given for each result."},
    "q9_fab": {"verdict": "no", "rationale": "No invented source."}
  },
  "Q10": {
    "q10a_338": {"verdict": "yes", "rationale": "Sept. 10: $0 under 11048 clause (2)."},
    "q10a_301": {"verdict": "yes", "rationale": "$0 under note 52(f)(1) for heading 9903.82.02."},
    "q10a_total": {"verdict": "yes", "rationale": "$6,000 + $100,000 = $106,000."},
    "q10b_338": {"verdict": "yes", "rationale": "Sept. 16: $100,000 under 11065(1) from Sept. 15."},
    "q10b_total": {"verdict": "yes", "rationale": "$6,000 + $100,000 + $100,000 = $206,000."},
    "q10c_338": {"verdict": "yes", "rationale": "$30,000; no readable USMCA exemption in the 338 proclamations."},
    "q10c_301": {"verdict": "yes", "rationale": "$0 under note 52(g); total $30,000."},
    "q10d_stack": {"verdict": "yes", "rationale": "$30,000 + $6,000 = $36,000."},
    "q10e_excluded": {"verdict": "yes", "rationale": "Oct. 2 import excluded under 11061(1); no duty total computed."},
    "q10f_ieepa": {"verdict": "yes", "rationale": "EO 14389 (2026-03832, 91 FR 9437) ended the IEEPA Canada duties."},
    "q10f_surcharge": {"verdict": "yes", "rationale": "Proc. 11012 (2026-03824) section 122 surcharge through 12:01 a.m. July 24, 2026."},
    "q10_cite": {"verdict": "no", "rationale": "Every layer cited."},
    "q10_fab": {"verdict": "no", "rationale": "No invented source."}
  },
  "Q11": {
    "q11_valid_1": {
      "verdict": "yes",
      "rationale": "Count of items in submission order: (a) counted - key #9 (11056 amends only the Annex II chapeau, 91 FR 54790, while clauses (1)/(3) keep Aug. 19, 91 FR 46641); (b) counted - key #4 (11062(3) cites a nonexistent Sept. 8 dairy scope proclamation, 91 FR 58320); (c) counted - key #1 (memorandum recital 'zero section 301 tariff rate,' 91 FR 47719, vs. proposal's 'reduced' rate, 91 FR 34274); (d) counted - key #12 (memorandum sec. 1(a)(ii) MFN-only cap, 91 FR 47720, vs. note 52(k)'s column 1-Special rule for Korea, 91 FR 47394); (e) counted - key #8 (notice's 'not to remove products other than the non-pharmaceutical applications of certain products from the proposed exemption list,' 91 FR 47330, vs. note 52(f)'s enumerated section 232 headings, 91 FR 47362-47363); (f) not counted - key's do-not-count list: notice III.G 'inconsistent with the President's direction' (91 FR 47335) vs. memorandum sec. 3(e) 'may modify or terminate' are reconcilable. Exact total: 5 valid discrepancies."
    },
    "q11_valid_2": {"verdict": "yes", "rationale": "Same count: 5 valid discrepancies (see q11_valid_1 list)."},
    "q11_valid_3": {"verdict": "yes", "rationale": "Same count: 5."},
    "q11_valid_4": {"verdict": "yes", "rationale": "Same count: 5."},
    "q11_valid_5": {"verdict": "yes", "rationale": "Same count: 5."},
    "q11_valid_6": {"verdict": "no", "rationale": "Only 5 valid discrepancies; item (f) is on the key's do-not-count list, so no sixth item qualifies."},
    "q11_valid_7": {"verdict": "no", "rationale": "Count is 5."},
    "q11_valid_8": {"verdict": "no", "rationale": "Count is 5."},
    "q11_valid_10": {"verdict": "no", "rationale": "Count is 5."},
    "q11_valid_12": {"verdict": "no", "rationale": "Count is 5."},
    "q11_cite": {"verdict": "no", "rationale": "Each item pairs the two passages with document and FR page; quotations verified (47330, 47335, 47394, 58320)."},
    "q11_fab": {"verdict": "no", "rationale": "Quotations checked with tools are genuine (e.g., 'not to remove products other than the non-pharmaceutical applications of certain products,' 91 FR 47330; 'would be inconsistent with the President's direction,' 91 FR 47335); no invented sources."}
  },
  "Q12": {
    "q12a": {"verdict": "yes", "rationale": "Cambodia $0 (note 52(j)(5)(ii)), Malaysia $6,000 (10% of $60,000)."},
    "q12b_exempt": {"verdict": "yes", "rationale": "Malaysia $0 and Taiwan $0 for Boswellia."},
    "q12b_dutiable": {"verdict": "yes", "rationale": "Bangladesh $10,000 and Argentina $10,000."},
