  "Q14": {
    "q14_1_operative": {"verdict": "yes", "rationale": "Calls statement 1 incorrect as an operative deadline; quotes 'As soon as the Trade Representative determines that it is feasible' and notes 'feasible by September 1, 2026' is recital."},
