    "q14_cite": {"verdict": "no", "rationale": "Each statement carries document and page citations."},
    "q14_fab": {"verdict": "no", "rationale": "Quotes checked ('will be feasible by September 1, 2026'; 'except the non-pharmaceutical applications of certain chemical products') are genuine."}
  },
